function FacturaCompra()
{
    $imp = new Login();
    $imp = $imp->ImpuestosPorId();
    $impuesto = (empty($imp) ? "IMPUESTO" : $imp[0]['nomimpuesto']);
    
    $tra = new Login();
    $reg = $tra->ComprasPorId();
    $simbolo = ($reg[0]['simbolo'] == "" ? "" : $reg[0]['simbolo']);
    $TipoLetra = "Courier";

