function TicketCreditoCompra()
{  
    $imp = new Login();
    $imp = $imp->ImpuestosPorId();
    $impuesto = ($imp == "" ? "IMPUESTO" : $imp[0]['nomimpuesto']);
    $valor = ($imp == "" ? "0.00" : $imp[0]['valorimpuesto']);

    $tra = new Login();
    $reg = $tra->ComprasPorId();
    $simbolo = ($reg[0]['simbolo'] == "" ? "" : $reg[0]['simbolo']);
    $TipoLetra = "Courier";

    if (file_exists("fotos/sucursales/".$reg[0]['cuitsucursal'].".png")) {

    $logo = "./fotos/sucursales/".$reg[0]['cuitsucursal'].".png";
    $this->Image($logo , 20, 3, 35, 15, "PNG");
    $this->Ln(8);

    }
  
    $this->SetX(2);
    $this->SetFont('Courier','B',12);
    $this->SetFillColor(2,157,116);
    $this->Cell(70, 5, "TICKET DE CR�DITO", 0, 0, 'C');
    $this->Ln(5);
  
    $this->SetX(2);
    $this->SetFont($TipoLetra,'B',10);
    $this->CellFitSpace(70,4,portales(_u8d($reg[0]['nomsucursal'])), 0, 1, 'C');

    $this->SetX(2);
    $this->SetFont($TipoLetra,'B',9);
    $this->CellFitSpace(70,3,$reg[0]['documsucursal'] == '0' ? "" : "N� ".$reg[0]['documento']." "._u8d($reg[0]['cuitsucursal']),0,1,'C');

    if($reg[0]['id_departamento']!='0'){

    $this->SetX(2);
    $this->CellFitSpace(70,3,_u8d($departamento = ($reg[0]['id_departamento'] == '0' ? "" : $reg[0]['departamento'])." ".$provincia = ($reg[0]['id_provincia'] == '0' ? "" : $reg[0]['provincia'])),0,1,'C');

    }

    $this->SetX(2);
